mapper.select:
SELECT COALESCE(asset.department_id, supply.department_id, reimbursement.department_id, purchase.department_id) AS department_id, COALESCE(asset.asset_count, 0) AS asset_count, COALESCE(asset.asset_quantity, 0) AS asset_quantity, COALESCE(asset.asset_value, 0) AS asset_value, COALESCE(supply.supply_sku_count, 0) AS supply_sku_count, COALESCE(supply.supply_stock, 0) AS supply_stock, COALESCE(supply.supply_min_stock, 0) AS supply_min_stock, COALESCE(reimbursement.reimbursement_count, 0) AS reimbursement_count, COALESCE(reimbursement.reimbursement_amount, 0) AS reimbursement_amount, COALESCE(purchase.purchase_count, 0) AS purchase_count, COALESCE(purchase.purchase_budget, 0) AS purchase_budget FROM ( SELECT department_id, COUNT(*) AS asset_count, COALESCE(SUM(quantity), 0) AS asset_quantity, COALESCE(SUM(acquisition_amount), 0) AS asset_value FROM spectra_oa.oa_asset WHERE deleted IS NULL AND department_id IS NOT NULL AND department_id IN
#{departmentId}
GROUP BY department_id ) asset FULL OUTER JOIN ( SELECT department_id, COUNT(*) AS supply_sku_count, COALESCE(SUM(current_stock), 0) AS supply_stock, COALESCE(SUM(min_stock), 0) AS supply_min_stock FROM spectra_oa.oa_supply_item WHERE deleted IS NULL AND department_id IS NOT NULL AND department_id IN
#{departmentId}
GROUP BY department_id ) supply USING (department_id) FULL OUTER JOIN ( SELECT department_id, COUNT(*) AS reimbursement_count, COALESCE(SUM(total_amount), 0) AS reimbursement_amount FROM spectra_oa.oa_reimbursement WHERE deleted IS NULL AND department_id IS NOT NULL AND department_id IN
#{departmentId}
GROUP BY department_id ) reimbursement USING (department_id) FULL OUTER JOIN ( SELECT department_id, COUNT(*) AS purchase_count, COALESCE(SUM(budget_amount), 0) AS purchase_budget FROM spectra_oa.oa_purchase WHERE deleted IS NULL AND department_id IS NOT NULL AND department_id IN
#{departmentId}
GROUP BY department_id ) purchase USING (department_id) ORDER BY department_id
